                v-model="projectName"
                @keyup.enter="addProject()"
              />
              <span
                :class="message.error?'error-message':'success-message'"
                v-if="message.value"
              >{{message.value}}</span>
            </div>
          </div>
          <AspectRatioSelection v-if="isMoodboardProject" @aspectRatioChange="handleARChage"></AspectRatioSelection>
          <div class="invite-button-container">
            <button @click="cancelContainer('invite')" class="cancel-button">{{ $t("buttonText.cancel") }}</button>
            <button @click="addProject()" :disabled="!projectName" class="update-address">{{ $t("buttonText.startNow") }}</button>
          </div>
        </div>
      </div>
    </div>
