</template>
<script>
import { mapGetters, mapState, mapActions, mapMutations } from "vuex";
import inviteComponent from "@/components/shared/invite";
import moodboardSignPopup from "@/components/shared/popups/moodboardSignupPopup.vue";
import moodboardBasicPaywall from "@/components/shared/popups/moodboardBasicPaywall.vue";
import cancelConfirmationPopup from "@/components/shared/popups/cancelConfirmationPopup.vue";
import CommonUtilities from "@/mixins/commonUtilitiesMixin"
import MoodboardDashboardMixin from "@/mixins/moodboardDashboardMixin"
import AspectRatioSelection from "@/components/AspectRatioSelection.vue";
import PayAsYouGoMixin from "@/mixins/payAsYouGoMixin";

export default {
    mixins: [
      CommonUtilities,
      MoodboardDashboardMixin,
      PayAsYouGoMixin
    ],
    components: {
      inviteComponent,
      moodboardSignPopup,
      AspectRatioSelection,
      moodboardBasicPaywall,
      cancelConfirmationPopup,
    },
    data() {
        return {
            newMember: false,
            message: {
                value: "",
                error: false,
                global: false,
            },
            inviteFriendEmail: "",
            projectName: undefined,
            newProject: false,
            showUpgardePopup: false,
            isMoodboardProject: false,
            selectedAspectRatio: null
        };
    },
    watch: {
      user: function(data) {
        if (data) {
          const { accountId } = data;
          this.getServiceList(accountId)
        }
      }
    },
    computed: {
        ...mapGetters("Billing", ['hasMoodBoardPlanExpired' ,'isMoodBoardPlanCancelled', 'isUserAMoodboardUser', 'hasNeoPaidPlanExpired' , "isNeoPaidPlanCancelled", "isUserOnPayAsYouGoPlan"]),
        ...mapGetters("User", ["isAPCatalogServiceAssigned", "isUserIndian", "isFoyrAIUser"]),

        ...mapState({
            user: (state) => state.User.user,
            usersProjects: (state) => state.Projects.usersProjects,
            usersProjectsWithPagination: (state) =>
                state.Projects.usersProjectsPagination,
            isTrial: (state) => state.Billing.isTrial,
            isBetaClicked: state => state.User.isBetaClicked,
            currentSubscription: state =>  state.Billing.currentSubscription,
            currentMoodboardSubscription: state =>  state.Billing.currentMoodboardSubscription,
            switchToMoodboard: state => state.User.switchToMoodboard,
            isUserAPDesigner: state => state.User.isUserAPDesigner,
            selectedLocale: state => state.User.selectedLocale
        }),
        getAccountsPageToLink() {
          if (this.switchToMoodboard) return '/moodboard/settings/profile'
          return (this.isTrial && this.user && this.user.accountType == 'root' && this.user.accountInfo.accountCategory == 'REGULAR') ? '/settings/plans_new': '/settings/plans'
        },
        // headerTextForProjects(){
        //   if(this.switchToMoodboard){
        //     return 'MoodBoards'
        //   }else{
        //     return 'Projects'
        //   }
        // },
    },

    methods: {
        ...mapActions({
            uploadProjects: "Projects/newProject",
            uploadBetaProjects: "newProjects/newProject",
            inviteFriend: "Dash/inviteFriend",
            getProjectsWithPagination: "Projects/getProjectsWithPagination",
            fetchFolders: "Projects/fetchFoldersTree",
            fetchProjects: 'Projects/fetchProjects',
            getServiceList: 'User/getServiceList'
        }),
        ...mapActions("typeformPopup", ["openEmbededTypeform"]),
        // ...mapActions("neoformPopup", ["openNeoformPopup"]),
        ...mapMutations({
            setProjectsFromComponent: "Projects/setProjectsFromComponent",
            setIsDFUPopupVisible: "Projects/setIsDFUPopupVisible",
            setGetFreeDemoShow_Desk: "Dash/setGetFreeDemoShow_Desk",
            setShowMoodboardBasicPaywall: "Dash/setShowMoodboardBasicPaywall",
        }),
        ...mapMutations("Projects", ["setShowAIIdeateRedirectPopup", "setDFUTypeFormLink", "setShowFoyrServicesPopup"]),
        closePopup() {
            this.newProject = false;
            this.projectName = undefined;
            this.newMember = false;
            this.inviteFriendEmail = "";
            this.showUpgardePopup = false;
            this.isMoodboardProject = false;
            this.selectedAspectRatio = null;
            // this.message = {};
        },
        closePopupForUpgrade() {
            this.showUpgardePopup = false;
              window.analytics.track('newproject_paywal_later', {
                title: 'NEW_PROJECT_PAYWALL',
                subtitle: 'NEW_PROJECT_PAYWALL',
            }, { 'integrations': { "Amplitude": { "session_id": new Date().getTime() } } }, { "timestamp": new Date().getTime() });

        },
        createNewProjectPopupTrigger(){

          if(!this.currentSubscription && !this.isUserAMoodboardUser) return

          let today = new Date().getTime();
          if(this.currentSubscription){

            if( this.currentSubscription &&
                this.currentSubscription.analyticsData &&
                (
                  (this.currentSubscription.analyticsData.analyticsStatus == "Trial expired") ||
                  (
                    (this.currentSubscription.analyticsData.analyticsStatus == "Cancelled" &&
                    this.currentSubscription.subscriptionExpiryDate &&
                    ( new Date( this.currentSubscription.subscriptionExpiryDate ).getTime() - today ) <= 0 )
                  )
                )
              ){
                this.showUpgardePopup =  true
                 window.analytics.track('newproject_paywall', {
                  title: 'NEW_PROJECT_PAYWALL',
                  subtitle: 'NEW_PROJECT_PAYWALL',
              }, { 'integrations': { "Amplitude": { "session_id": new Date().getTime() } } }, { "timestamp": new Date().getTime() });

                return
            }
          }
          if(this.switchToMoodboard && this.isUserAMoodboardUser) {
            if (
                this.hasMoodBoardPlanExpired ||
                (this.isMoodBoardPlanCancelled && this.currentMoodboardSubscription.chargebeeSubscriptionData.status !== "non_renewing")
            ) {
              this.setShowMoodboardBasicPaywall(true)
              return
            }
            this.isMoodboardProject = this.switchToMoodboard;
          }
          this.newProject = true
        },
        cancelContainer(container) {
            if (container == "invite") {
                this.newProject = false;
                this.projectName = undefined;
                this.isMoodboardProject = false;
            } else {
                // this.message = {};
            }
        },
        async addProject() {
            // if (this.isMoodboardProject) {
            //   this.addMoodboardProject();
            //   return;
            // }
            // const namePattern = /^[A-Za-z0-9_ ]*$/;
            const namePattern = /^[\u3040-\u309F\u30A0-\u30FF\u4E00-\u9FAF\u00C0-\u00FFA-Za-z0-9_ ]*$/;
            let error = false;
            let errorType = "";
            if (!this.projectName || this.projectName.trim("").length <= 0) {
                error = true;
                errorType = "any.empty";
            }
            if (this.projectName) {
                if (this.projectName.length >= 50) {
                    error = true;
                    errorType = "max.limit";
                } else if (this.projectName.trim("").length <= 1) {
                    error = true;
                    errorType = "min.limit";
                }
            }
            let testValue = namePattern.test(this.projectName);
            if (!testValue) {
                error = true;
                errorType = "string.regex.base";
            }
            switch (errorType) {
                case "any.empty":
                    this.message.value = "Name should not be empty!";
                    break;
                case "string.min":
                    this.message.value = `Name should have at least ${err.context.limit} characters!`;
                    break;
                case "string.max":
                    this.message.value = `Name should have at most ${err.context.limit} characters!`;
                    break;
                case "string.regex.base":
                    this.message.value = `Name can contain only alphanumeric characters, spaces and underscores.`;
                    break;
                case "max.limit":
                    this.message.value =
                        "Name should have at most 50 characters!";
                    break;
                case "min.limit":
                    this.message.value =
                        "Name should have at least 2 characters!";
                    break;
                default:
                    break;
            }
            if (!error) {
                console.log("Project Name*********************ASIDE");
                if (!this.usersProjects) {
                  await this.fetchProjects().then(res => { });
                }
                let projectNameDup = this.projectName;
                var projectsDuplicate = [];
                projectsDuplicate = this.usersProjects.filter(function (
                    project
                ) {
                    if (project && project.name) {
                        return (
                            project.name.toUpperCase() ===
                            projectNameDup.toUpperCase()
                        );
                    }
                });
                if (projectsDuplicate && projectsDuplicate.length > 0) {
                    this.message.error = true;
                    this.message.value = "Project name already exists.";
                    setTimeout(() => {
                        this.message.global = false;
                        this.message.value = "";
                    }, 2500);
                    return;
                }
                let serviceName = 'CREATE_NEW_PROJECT';
                if ( this.isUserOnPayAsYouGoPlan ) {
                    if ( this.creditsRequiredForService( serviceName ) > this.totalCreditsAvailable ) {
                        this.message.error = true;
                        this.message.global = false;
                        this.message.value = "Not Enough Credits";
                        setTimeout(() => {
                            this.message.error = false;
                            this.message.global = false;
                            this.message.value = '';
                        }, 2000);
                    } else if ( this.showCreditsConfirmationPopupForService( serviceName ) ) {
                        this.openConfirmationPopupConfig( {
                            bodyTextRef: this.$t( "payAsYouGo.serviceChargeText", { creditsRequired: this.creditsRequiredForService( serviceName ) } ),
                            buttonClickCB: async ( data ) => {
                                if ( data ) {
                                    this.updateDoNotShowCreditsPopupForService( { service: serviceName } );
                                }
                                this.closeConfirmationPopupConfig();
                                this.createNewProject();
                            }
                        } );
                    } else {
                        this.createNewProject();
                    }
                } else {
                    this.createNewProject();
                }
            } else {
                this.message.error = true;
                setTimeout(() => {
                    this.message.global = false;
                    this.message.value = "";
                }, 2500);
                // this.message.value = "Please enter project name";
            }
        },
        createNewProject() {
            this.uploadProjects({
              type: ["project"],
              name: this.projectName,
              ...(this.isMoodboardProject && { isMBProject: true }),
              ...(this.isMoodboardProject && { canvasDimension: this.getHeightAndWidth(this.selectedAspectRatio) }),
            })
                .then((res) => {
                    if (res.error) {
                        this.message.error = true;
                    } else {
                        amplitude
                            .getInstance()
                            .logEvent("projectAddedFromSideBar");
                        if (window.analytics) {
                            window.analytics.track(
                                "New Project",
                                {
                                    title: "Clone Project",
                                    subtitle: "projectAddedFromSideBar",
                                },
                                {
                                    integrations: {
                                        Amplitude: {
                                            session_id: new Date().getTime(),
                                        },
                                    },
                                }
                            );
                        }
                        this.fetchFolders({});
                        this.newProject = false;
                        this.isMoodboardProject = false;
                        this.projectName = undefined;
                        this.message.error = false;
                        this.message.value = res.message;
                        this.message.global = true;
                        this.$root.$emit("add-project-main");
                        this.getProjectsWithPagination({
                            pageSize: 20,
                            pageNum: 1,
                        })
                            .then((res) => {
                                this.setProjectsFromComponent(res);
                            })
                            .catch((err) => {
                                console.log(err);
                            });
                        setTimeout(() => {
                            this.message.global = false;
                            this.message.value = "";
                        }, 2000);
                        localStorage.setItem("newProject", true);
                        if (window.analytics && res.isMBProject) {
                          window.analytics.track(
                            "MB_create_project",
                            {
                              title: "MB create project",
                              subtitle: res.id,
                              // author: this.user._id
                            },
                            {
                              integrations: {
                                Amplitude: { session_id: new Date().getTime() }
                              }
                            }
                          );
                        }
                        if (
                            this.user &&
                            this.user.whitelabelData &&
                            this.user.whitelabelData.hasOwnProperty(
                                "redirectProject"
                            ) &&
                            !this.user.whitelabelData.redirectProject
                        ) {
                            window.location.href =
                                window.location.origin +
                                `${res.isMBProject? '/moodboard?project=' :res.v2Project ? '/toolv2?project=': '/tool?project='}` +
                                res.id + this.checkLangAndReturnLangCode();
                        } else {
                            if (this.isSafari()) {
                              window.location = window.location.origin + `${res.isMBProject? '/moodboard?project=' :res.v2Project ? '/toolv2?project=': '/tool?project='}` + res.id + this.checkLangAndReturnLangCode();
                            } else {
                              window.open( window.location.origin + `${res.isMBProject? '/moodboard?project=' :res.v2Project ? '/toolv2?project=': '/tool?project='}` +res.id + this.checkLangAndReturnLangCode() );
                            }
                        }
                    }
                })
                .catch((error) => {
                    console.log(error)
                    this.message.value =
                        error.data && error.data.err && error.data.err.message
                            ? error.data.err.message
                            : "Internal Server Error";
                    this.message.error = true;
                    setTimeout(() => {
                        this.message.error = false;
                        this.message.value = "";
                    }, 2000);
                });
        },
        createNewBetaProject() {
            this.uploadBetaProjects({
                type: ["project"],
                name: this.projectName,
            })
                .then((res) => {
                    if (res.error) {
                        this.message.error = true;
                    } else {
                        amplitude
                            .getInstance()
                            .logEvent("projectAddedFromSideBar");
                        if (window.analytics) {
                            window.analytics.track(
                                "New Project",
                                {
                                    title: "Clone Project",
                                    subtitle: "projectAddedFromSideBar",
                                },
                                {
                                    integrations: {
                                        Amplitude: {
                                            session_id: new Date().getTime(),
                                        },
                                    },
                                }
                            );
                        }
                        this.fetchFolders({});
                        this.newProject = false;
                        this.projectName = undefined;
                        this.message.error = false;
                        this.message.value = res.message;
                        this.message.global = true;
                        this.$root.$emit("add-project-main");
                        this.getProjectsWithPagination({
                            pageSize: 20,
                            pageNum: 1,
                        })
                            .then((res) => {
                                this.setProjectsFromComponent(res);
                            })
                            .catch((err) => {
                                console.log(err);
                            });
                        setTimeout(() => {
                            this.message.global = false;
                            this.message.value = "";
                        }, 2000);
                        localStorage.setItem("newProject", true);
                        if (
                            this.user &&
                            this.user.whitelabelData &&
                            this.user.whitelabelData.hasOwnProperty(
                                "redirectProject"
                            ) &&
                            !this.user.whitelabelData.redirectProject
                        ) {
                            window.location.href =
                                window.location.origin +
                                `${res.v2Project ? '/toolv2?project=': '/tool?project='}` +
                                res.id + this.checkLangAndReturnLangCode();
                        } else {
                            if (this.isSafari()) {
                              window.location = window.location.origin + `${res.v2Project ? '/toolv2?project=': '/tool?project='}` + res.id + this.checkLangAndReturnLangCode();
                            }
                            else {
                              window.open( window.location.origin + `${res.v2Project ? '/toolv2?project=': '/tool?project='}` + res.id + this.checkLangAndReturnLangCode());
                            }
                        }
                    }
                })
                .catch((error) => {
                    this.message.value =
                        error.data && error.data.err && error.data.err.message
                            ? error.data.err.message
                            : "Internal Server Error";
                    this.message.error = true;
                    setTimeout(() => {
                        this.message.error = false;
                        this.message.value = "";
                    }, 2000);
                });
        },
        helpClicked: function () {
            analytics.track(
                "Help",
                {
                    title: "Help",
                    subtitle: "Clicked",
                },
                {
                    integrations: {
                        Amplitude: { session_id: new Date().getTime() },
                    },
                },
                { timestamp: new Date().getTime() }
            );
        },
        inviteLink() {
            if (this.inviteFriendEmail) {
                this.inviteFriend({ email: this.inviteFriendEmail })
                    .then((res) => {
                        this.newMember = false;
                        this.inviteFriendEmail = "";
                        this.message.error = false;
                        this.message.value = res.message;
                        this.message.global = true;
                        setTimeout(() => {
                            this.message.global = false;
                            this.message.value = "";
                        }, 4000);
                        if (window.analytics) {
                            window.analytics.track(
                                "Refer a Friend",
                                {
                                    title: "Refer a Friend",
                                    subtitle: "mobile",
                                },
                                {
