                                            session_id: new Date().getTime(),
                                        },
                                    },
                                },
                                { timestamp: new Date().getTime() }
                            );
                        }
                    })
                    .catch((err) => {
                        this.message.global = true;
                        this.message.error = true;
                        this.message.value = "Something went wrong!";
                        setTimeout(() => {
                            this.message.global = false;
                            this.message.value = "";
                        }, 2500);
                    });
            } else {
                this.message.global = true;
                this.message.error = true;
                this.message.value = "Email is required";
                setTimeout(() => {
                    this.message.global = false;
                    this.message.value = "";
                }, 2500);
            }
        },
        inviteClicked: function () {
            analytics.track(
                "INVITE",
                {
                    title: "Invite",
                    subtitle: "Clicked",
                },
                {
                    integrations: {
                        Amplitude: { session_id: new Date().getTime() },
                    },
                },
                { timestamp: new Date().getTime() }
            );
            this.newMember = true;
        },
        onUpgradeClick() {
           window.analytics.track('newproject_paywal_upgrade', {
          title: 'NEW_PROJECT_PAYWALL',
          subtitle: 'NEW_PROJECT_PAYWALL',
      }, { 'integrations': { "Amplitude": { "session_id": new Date().getTime() } } }, { "timestamp": new Date().getTime() });
            window.open(window.location.origin + this.localePath('/settings/plans_new'), "_blank")
        },
        handleARChage(aspectRatio) {
          this.selectedAspectRatio = aspectRatio.text;
        },
        getHeightAndWidth(aspectRatio) {
          if (!aspectRatio) return {};

          switch(aspectRatio) {
            case "4:3": {
              return {
                height: 900,
                width: 1200
              }
            }
            case "Square": {
              return {
                height: 900,
                width: 900
              }
            }
            case "Potrait": {
              return {
                height: 1200,
                width: 900
              }
            }
            case "16:9":
            default: {
              return {
                height: 900,
                width: 1600
              }
            }
          }
        },
        onReferAndEarnButtonClick() {
          if (window.analytics) {
            window.analytics.track(
              "click_refer_and_earn",
              {
                name: "Click refer and earn",
                event_category: "Refer and Earn",
              },
              {
                integrations: {
                  Amplitude: { session_id: new Date().getTime() },
                },
              },
              { timestamp: new Date().getTime() }
            );
          }
        },
        checkLangAndReturnLangCode() {
          switch(this.$i18n.locale) {
            case "ja": {
              return "&lang=ja&isAtlasSearchEnabled=true"
            }
            case "es": {
              return "&lang=es&isAtlasSearchEnabled=true"
            }
          }

          return ""
        },
        OnDesingForYouButtonClick() {
          // this.setDFUTypeFormLink("https://form.typeform.com/to/dC7q0Gex?utm_source=product&utm_medium=dashboard&utm_campaign=sidepanel")
          // this.setIsDFUPopupVisible(true)
          if (window.analytics) {
            window.analytics.track("Click DFU on DB sidepanel", {
              title: "Click DFU on DB sidepanel",
            }, { 'integrations': { "Amplitude": { "session_id": new Date().getTime() } } }, { "timestamp": new Date().getTime() });
          }
          this.openEmbededTypeform({
            formId: 'dC7q0Gex',
            hidden: {
              utm_source: "product",
              utm_medium: "dashboard",
              utm_campaign: "sidepanel",
            },
          })
          // window.open("https://form.typeform.com/to/dC7q0Gex?utm_source=product&utm_medium=dashboard&utm_campaign=sidepanel", '_blank')
        },
        onClickAIDesigns() {
          this.setShowAIIdeateRedirectPopup(true)
          this.sendEventToTrack("Clicked AI designs on DB")
        },
        OnFoyrServicesButtonClick() {
          console.log("on foyr service button click");
          this.setShowFoyrServicesPopup(true)
          // this.openNeoformPopup({
					// 	neoFormUrl: 'https://neostaging.foyr.com/forms#/'
					// });
        }
    },
};
